/* The tables of M14 · Student attendance. */

/** One marking of one section: for a day, or for one lesson in period mode. */
export const attendanceSessions = defineTable(
  'attendance_sessions',
  { module: 'M14', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    sectionId: uuid()
      .references((): AnyPgColumn => sections.id)
      .notNull(),
    /** not in the future */
    sessionDate: dateStr().notNull(),
    /** `0` for a daily session, the lesson number in period mode */
    lessonNo: integer().notNull(),
    /** period mode */
    sectionSubjectId: uuid().references((): AnyPgColumn => sectionSubjects.id),
    takenBy: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
    status: enumText(attendanceSessionStatuses).notNull().default('draft'),
    source: enumText(attendanceSessionSources).notNull().default('manual'),
    submittedAt: timestamptz(),
    lockedAt: timestamptz(),
    note: text(),
  },
  (t) => [
    nonNegative('attendance_sessions', t.lessonNo),
    uniqueIndex('attendance_sessions_section_session_date_lesson_no_uq')
      .on(t.sectionId, t.sessionDate, t.lessonNo)
      .where(live(t)),
    index('attendance_sessions_branch_session_date_idx').on(t.orgId, t.branchId, t.sessionDate),
  ],
);

export const attendanceRecords = defineTable(
  'attendance_records',
  { module: 'M14', scope: 'branch', family: 'studentId' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    sessionId: uuid()
      .references((): AnyPgColumn => attendanceSessions.id)
      .notNull(),
    studentId: uuid()
      .references((): AnyPgColumn => students.id)
      .notNull(),
    enrollmentId: uuid()
      .references((): AnyPgColumn => enrollments.id)
      .notNull(),
    /** copied from the session for fast filtering */
    sessionDate: dateStr().notNull(),
    status: enumText(attendanceRecordStatuses).notNull(),
    minutesLate: integer(),
    note: text(),
    markedAt: timestamptz().notNull(),
    markedBy: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
    source: enumText(attendanceRecordSources).notNull().default('manual'),
    /** a person changed what a machine recorded */
    isManualOverride: boolean().notNull().default(false),
  },
  (t) => [
    nonNegative('attendance_records', t.minutesLate),
    uniqueIndex('attendance_records_session_student_uq')
      .on(t.sessionId, t.studentId)
      .where(live(t)),
    index('attendance_records_student_session_date_idx').on(t.orgId, t.studentId, t.sessionDate),
    index('attendance_records_branch_session_date_status_idx').on(
      t.orgId,
      t.branchId,
      t.sessionDate,
      t.status,
    ),
  ],
);

export const studentLeaveRequests = defineTable(
  'student_leave_requests',
  {
    module: 'M14',
    scope: 'branch',
    family: 'studentId',
    familyRule: { read: true, insert: { status: 'pending' }, update: { status: 'pending' } },
  },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    studentId: uuid()
      .references((): AnyPgColumn => students.id)
      .notNull(),
    fromDate: dateStr().notNull(),
    /** at most 30 days later */
    toDate: dateStr().notNull(),
    reason: enumText(studentLeaveRequestReasons).notNull(),
    detail: text(),
    /** a medical note */
    fileId: uuid().references((): AnyPgColumn => files.id),
    requestedVia: enumText(studentLeaveRequestRequestedViaOptions).notNull().default('portal'),
    status: enumText(studentLeaveRequestStatuses).notNull().default('pending'),
    decidedBy: uuid().references((): AnyPgColumn => profiles.id),
    decidedAt: timestamptz(),
    decisionNote: text(),
  },
  (t) => [
    check('student_leave_requests_to_date_from', sql`${t.toDate} >= ${t.fromDate}`),
    check('student_leave_requests_to_date_span', sql`${t.toDate} <= ${t.fromDate} + 30`),
  ],
);

/** A change asked for after the day is locked. */
export const attendanceCorrections = defineTable(
  'attendance_corrections',
  { module: 'M14', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    recordId: uuid()
      .references((): AnyPgColumn => attendanceRecords.id)
      .notNull(),
    fromStatus: text().notNull(),
    toStatus: enumText(attendanceCorrectionToStatuses).notNull(),
    reason: text().notNull(),
    status: enumText(attendanceCorrectionStatuses).notNull().default('pending'),
    decidedBy: uuid().references((): AnyPgColumn => profiles.id),
    decisionNote: text(),
  },
);
